-- ADP for the 2025 season from Fantasy Football Calculator (fantasyfootballcalculator.com).
-- Run migration 0006 first. Safe to re-run: existing rows are updated.
on conflict (player_id, source, season, format, scoring, qb_type) do update set
  adp=excluded.adp, high=excluded.high, low=excluded.low, stdev=excluded.stdev,
  times_drafted=excluded.times_drafted, teams=excluded.teams, as_of=excluded.as_of;
